#!/usr/bin/env node
// Builds the TipTap markdown-editor bundle served at
// /custom-mobile-compat/text-editor/tiptap.bundle.js
//
// Output:
//   src/applications/custom-mobile-compat/assets/tiptap.bundle.js
//
// Run:  node scripts/build-nc-markdown-editor.mjs
// Or:   npm run build:nc-markdown-editor
//
// Like the CodeMirror bundle, the output is committed to git so the deployed
// server has it without running the build at deploy time. Re-run when TipTap
// or one of its extensions is bumped, then commit the regenerated file.
//
// The page renderer (utils/markdown-editor-page.ts) loads the bundle via
// dynamic `import(bundleUrl)` and reads `mod.mountTipTap`. The source pins a
// `window.NcMarkdownEditor.mountTipTap` global as a fallback.

import { build } from 'esbuild'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

const __dirname = dirname(fileURLToPath(import.meta.url))
const ROOT = join(__dirname, '..')
const ENTRY = join(ROOT, 'scripts', 'nc-markdown-editor-src', 'index.js')
const OUT = join(ROOT, 'src', 'applications', 'custom-mobile-compat', 'assets', 'tiptap.bundle.js')

await build({
  entryPoints: [ENTRY],
  outfile: OUT,
  bundle: true,
  format: 'esm',
  // Same target floor as the CodeMirror bundle — NC iOS 33.x requires iOS 16+
  // which ships Safari 16, well within our destructuring/optional-chain needs.
  target: ['es2022', 'safari15'],
  minify: true,
  sourcemap: false,
  loader: { '.css': 'text' },
  legalComments: 'none',
  banner: { js: '/* TipTap bundle for Sync-in NC markdown editor — generated by scripts/build-nc-markdown-editor.mjs */' }
})

console.log(`Built ${OUT}`)
